import React, { useEffect, useRef } from 'react';
import styled from 'styled-components';

import { RangeLegendAnchorItemLabel } from './RangeLegendAnchorItemLabel.js';
import { RangeLegendItemLabel } from './RangeLegendItemLabel.js';
import { RangeLegendSegmentsItem } from './RangeLegendSegmentsItem.js';
import { Flex } from '../../../../../../layouts-core/flex/Flex.js';
import { useLegendSize } from '../../shared/context/LegendSizeContext.js';
import { RANGE_LEGEND_PADDING, RANGE_SORTING } from '../constants.js';
import { useOrientation } from '../context/RangeLegendOrientationContext.js';
import { useScale } from '../context/RangeLegendScaleContext.js';
import { useVariant } from '../context/RangeLegendVariantContext.js';
import { getDivergentPointData } from '../functions/get-divergent-point-data.js';
import { useLabelsVisibilityMap } from '../hooks/useLabelsVisibilityMap.js';
import { RangeItem } from '../types/range-legend.js';

const StyledSVG = styled('svg')({
  overflow: 'visible',
});

interface RangeLegendDivergentSegmentsProps {
  items: RangeItem[];
}

export const RangeLegendDivergentSegments = (
  props: RangeLegendDivergentSegmentsProps,
) => {
  const { items } = props;
  const { width, height } = useLegendSize();
  const containerWidth = -width - RANGE_LEGEND_PADDING * 2;
  const containerHeight = -height - RANGE_LEGEND_PADDING * 2;
  const { scale, sorting } = useScale();
  const { orientation } = useOrientation();
  const { variant } = useVariant();
  const labelsRef = useRef<SVGTextElement[]>([]);

  const divergentPoint = getDivergentPointData(
    items,
    orientation,
    containerWidth,
    containerHeight,
  );

  const labelsMap = useLabelsVisibilityMap(
    items,
    labelsRef.current,
    orientation,
    variant,
  );

  const legendItems = items.reduce(
    (acc, item, index) => {
      const startingRange = sorting === RANGE_SORTING.ASC ? 'from' : 'to';
      const endingRange = sorting === RANGE_SORTING.ASC ? 'to' : 'from';

      const isDivergentPoint = index === divergentPoint.index;
      const isPointAfterDivergent = index > divergentPoint.index;
      const lastItemIndex = items.length - 1;
      const isAnchorItem =
        [0, lastItemIndex].includes(index) || isDivergentPoint;

      const divergentPointSegment = isPointAfterDivergent
        ? divergentPoint.size
        : 0;

      const startPosition = scale(item[startingRange])! + divergentPointSegment;
      const size = isDivergentPoint
        ? divergentPoint.size
        : scale(item[endingRange])! + divergentPointSegment - acc.usedWidth;

      const newItem = (
        <RangeLegendSegmentsItem
          key={`${item.from}-${item.to}`}
          size={size}
          startPosition={startPosition}
          color={item.color}
          showGap={index === lastItemIndex}
        >
          {!isAnchorItem && (
            <RangeLegendItemLabel
              ref={(el) => el && (labelsRef.current[index] = el)}
              startPosition={startPosition}
              itemSegmentSize={size}
              text={
                isPointAfterDivergent
                  ? item[endingRange].toString()
                  : item[startingRange].toString()
              }
              alignment={isPointAfterDivergent ? 'end' : 'start'}
              hidden={labelsMap.has(index)}
            />
          )}
          {isAnchorItem && (
            <RangeLegendAnchorItemLabel
              ref={(el) => el && (labelsRef.current[index] = el)}
              items={items}
              index={index}
              offset={divergentPointSegment}
              isDivergentPoint={isDivergentPoint}
            />
          )}
        </RangeLegendSegmentsItem>
      );

      return {
        items: [...acc.items, newItem],
        usedWidth: acc.usedWidth + size,
      };
    },
    {
      items: [] as JSX.Element[],
      usedWidth: 0,
    },
  );

  useEffect(() => {
    const newLabelsRef = [] as SVGTextElement[];
    labelsRef.current = newLabelsRef;
  }, [items, width, height, orientation]);

  return (
    <Flex width={width} height={height}>
      <StyledSVG>{legendItems.items}</StyledSVG>
    </Flex>
  );
};

RangeLegendDivergentSegments['displayName'] = 'RangeLegendDivergentSegments';
